package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.os.*;
import android.text.InputType;
import android.widget.*;
import java.util.*;
/** Profile-scoped edit lock. Credentials deliberately excluded from setups, AI drafts and exports. */
final class LauncherLock {
    static final String KEY="private_layout_lock_v1";private static String unlocked="";private static long until,blockedUntil;private static int failures;
    static boolean enabled(Context c){return !ProfileStore.preferences(c).getString(KEY,"").isEmpty();}
    static boolean open(Context c){return !enabled(c)||ProfileStore.id().equals(unlocked)&&SystemClock.elapsedRealtime()<until;}
    static boolean require(Activity a,Runnable after){if(open(a))return true;if(SystemClock.elapsedRealtime()<blockedUntil){Toast.makeText(a,"Please wait before trying another PIN",Toast.LENGTH_LONG).show();return false;}String profile=ProfileStore.id(),record=ProfileStore.preferences(a).getString(KEY,"");EditText pin=field(a,"Layout PIN");AlertDialog d=new AlertDialog.Builder(a).setTitle("Unlock layout editing").setMessage("This only protects launcher editing. It does not lock Android, streaming accounts or other profiles.").setView(pin).setNegativeButton(android.R.string.cancel,(x,w)->{if(a instanceof LauncherSettingsActivity)a.finish();}).setPositiveButton("Unlock",null).create();d.setOnCancelListener(x->{if(a instanceof LauncherSettingsActivity)a.finish();});d.setOnShowListener(x->{pin.requestFocus();d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{hide(a,pin);String input=pin.getText().toString();try{LockPolicy.validPin(input);}catch(Exception bad){pin.setError(bad.getMessage());return;}d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);new Thread(()->{boolean good=false;try{good=LockPolicy.verify(record,input);}catch(Exception ignored){}boolean accepted=good;new Handler(Looper.getMainLooper()).post(()->{if(a.isDestroyed()||a.isFinishing()||!d.isShowing())return;d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);pin.setText("");if(!profile.equals(ProfileStore.id())||!record.equals(ProfileStore.preferences(a).getString(KEY,""))){d.dismiss();return;}if(accepted){failures=0;unlocked=profile;until=SystemClock.elapsedRealtime()+300000;d.dismiss();after.run();}else{failures++;if(failures>=5){blockedUntil=SystemClock.elapsedRealtime()+30000;d.dismiss();if(a instanceof LauncherSettingsActivity)a.finish();}else pin.setError("PIN did not match");}});},"Verify layout PIN").start();});});pin.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_DONE){d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();return true;}return false;});d.show();return false;}
    private static void hide(Activity a,EditText field){((android.view.inputmethod.InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(field.getWindowToken(),0);}
    static void watch(Activity a,boolean ready){String profile=ProfileStore.id();Handler handler=new Handler(Looper.getMainLooper());Runnable guard=new Runnable(){public void run(){if(a.isFinishing()||a.isDestroyed())return;if(!profile.equals(ProfileStore.id())||ready&&!open(a)){a.finish();return;}if(ready&&enabled(a))handler.postDelayed(this,Math.max(1,until-SystemClock.elapsedRealtime()));}};a.getApplication().registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity x,Bundle b){}public void onActivityStarted(Activity x){}public void onActivityStopped(Activity x){}public void onActivitySaveInstanceState(Activity x,Bundle b){}public void onActivityResumed(Activity x){if(x==a){handler.removeCallbacks(guard);guard.run();}}public void onActivityPaused(Activity x){if(x==a)handler.removeCallbacks(guard);}public void onActivityDestroyed(Activity x){if(x==a){handler.removeCallbacksAndMessages(null);a.getApplication().unregisterActivityLifecycleCallbacks(this);}}});}
    static EditText field(Activity a,String hint){EditText v=new EditText(a);v.setHint(hint);v.setSingleLine(true);v.setSaveEnabled(false);v.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);v.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);v.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8)});return v;}
    static void settings(Activity a){if(!require(a,()->settings(a)))return;if(enabled(a)){String profile=ProfileStore.id(),record=ProfileStore.preferences(a).getString(KEY,"");new AlertDialog.Builder(a).setTitle("Layout lock").setMessage("Editing is unlocked for five minutes in this profile. The PIN is not included in saved setups or AI exports. Android app-data controls can reset it.").setNeutralButton("Lock now",(d,w)->{until=0;a.finish();}).setNegativeButton("Close",null).setPositiveButton("Remove lock",(d,w)->{if(!profile.equals(ProfileStore.id())||!record.equals(ProfileStore.preferences(a).getString(KEY,""))){a.finish();return;}Map<String,Object> values=new HashMap<>();values.put(KEY,null);if(!SetupValues.commit(ProfileStore.preferences(a),values))Toast.makeText(a,"Could not remove layout lock",Toast.LENGTH_LONG).show();a.finish();}).show();return;}
        LinearLayout body=new LinearLayout(a);body.setOrientation(LinearLayout.VERTICAL);EditText first=field(a,"New PIN (4–8 digits)"),confirm=field(a,"Repeat PIN");body.addView(first);body.addView(confirm);String profile=ProfileStore.id();AlertDialog d=new AlertDialog.Builder(a).setTitle("Protect layout editing").setMessage("A convenience lock for this profile. This does not restrict TV settings, streaming content or profile switching. Keep the PIN yourself; it cannot be recovered.").setView(body).setNegativeButton(android.R.string.cancel,null).setPositiveButton("Set PIN",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{hide(a,confirm);String pin=first.getText().toString();try{LockPolicy.validPin(pin);if(!pin.equals(confirm.getText().toString()))throw new IllegalArgumentException("PINs do not match");}catch(Exception bad){confirm.setError(bad.getMessage());return;}d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);new Thread(()->{String result=null;try{result=LockPolicy.create(pin);}catch(Exception ignored){}String record=result;new Handler(Looper.getMainLooper()).post(()->{if(a.isDestroyed()||a.isFinishing()||!d.isShowing())return;first.setText("");confirm.setText("");if(record==null||!profile.equals(ProfileStore.id())){d.dismiss();Toast.makeText(a,"Could not set layout lock",Toast.LENGTH_LONG).show();return;}Map<String,Object> values=new HashMap<>();values.put(KEY,record);if(SetupValues.commit(ProfileStore.preferences(a),values)){unlocked=profile;until=SystemClock.elapsedRealtime()+300000;d.dismiss();a.finish();}else{d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);confirm.setError("Could not save PIN");}});},"Create layout PIN").start();}));first.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_NEXT);first.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_NEXT){confirm.requestFocus();return true;}return false;});confirm.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_DONE){d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();return true;}return false;});d.show();
    }
}
